import unittest

from unique import stable_unique


class StableUniqueTests(unittest.TestCase):
    def test_preserves_order_and_first_occurrences(self):
        self.assertEqual(stable_unique([3, 1, 3, 2, 1, 4]), [3, 1, 2, 4])

    def test_supports_unhashable_lists_and_dicts(self):
        items = [[1, 2], {"a": 1}, [1, 2], {"a": 1}, [2, 1]]
        self.assertEqual(stable_unique(items), [[1, 2], {"a": 1}, [2, 1]])

    def test_mixed_values(self):
        self.assertEqual(stable_unique([None, "x", None, (1,), "x"]), [None, "x", (1,)])

    def test_empty_input(self):
        self.assertEqual(stable_unique([]), [])

    def test_does_not_mutate_input_or_reuse_it_as_result(self):
        items = [[1], [1], [2]]
        result = stable_unique(items)
        self.assertEqual(items, [[1], [1], [2]])
        self.assertEqual(result, [[1], [2]])
        self.assertIsNot(result, items)

    def test_single_item(self):
        item = object()
        self.assertEqual(stable_unique([item]), [item])


if __name__ == "__main__":
    unittest.main()
